int mergeSort(Buffer *buf, bool choice)
{
	int blkNum = choice ? S_BLK_NUM : R_BLK_NUM;      // 32 or 16
	unsigned int baseAddr = choice ? S_ADDR : R_ADDR; // 16 or 0
	unsigned int segAddr = choice ? MERGE_S_SEG_ADDR : MERGE_R_SEG_ADDR;
	unsigned int retAddr = choice ? MERGE_S_RET_ADDR : MERGE_R_RET_ADDR;

	int M = buf->numAllBlk; // 8
	// pass 1: segments of M-1 = 7 blocks (leave 1 block for output writer)
	int segBlks = M - 1;
	int numRuns = (blkNum + segBlks - 1) / segBlks; // R: 3, S: 5

	unsigned int runStart[16];
	pushToWrite(buf, NULL, 0, segAddr, true); // reset writer at segAddr
	for (int i = 0; i < numRuns; i++) {
		int n = min(segBlks, blkNum - i*segBlks);
		Relation tuples[7 * 7]; // up to 49 tuples
		int cnt = 0;
		for (int j = 0; j < n; j++) {
			unsigned char *blk = readBlockFromDisk(baseAddr + i*segBlks + j, buf);
			readTuplesFromBlock(blk, tuples + cnt);
			cnt += TUPLE_PER_BLK;
			freeBlockInBuffer(blk, buf);
		}
		sort by attr1 (stable not needed)
		runStart[i] = current write addr... 
	}
