		string type = (t[0]=='S') ? "SELECT" : "PROJECTION";
		size_t lb = t.find('['), rb = t.find(']');
		string info = trim(t.substr(lb+1, rb-lb-1));
		size_t lp = t.find('(', rb);
		// matching close paren = last char
		string inner = trim(t.substr(lp+1, t.rfind(')') - lp - 1));
		TreeNode *node = new TreeNode(type, info);
		node->left = parseNode(inner);
		return node;
	}
	size_t jp = t.find(" JOIN ");
	if (jp != string::npos) {
		TreeNode *node = new TreeNode("JOIN");
		node->left = new TreeNode("LEAF", trim(t.substr(0, jp)));
		node->right = new TreeNode("LEAF", trim(t.substr(jp+6)));
		return node;
	}
	return new TreeNode("LEAF", t);
}
void parseQuery(TreeNode *root, string query) { root->left = parseNode(query); }
