```cpp
void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
{
	static unsigned char *wblk = NULL;
	static size_t wused = 0;
	static unsigned int waddr = 0;
	if (reset) { wblk = NULL; wused = 0; waddr = addr; return; }
	if (push) {
		if (wblk != NULL) {
			unsigned int zero = 0;
			memcpy(wblk + BLK_SIZE - PTR_SIZE, &zero, PTR_SIZE);
			writeBlockToDisk(wblk, waddr, buf);
			wblk = NULL; wused = 0;
		}
		return;
	}
	if (wblk == NULL) {
		wblk = getNewBlockInBuffer(buf);
		memset(wblk, 0, BLK_SIZE);
		wused = 0;
	}
	if (wused + size > BLK_SIZE - PTR_SIZE) {
		unsigned int next = waddr + 1;
		memcpy(wblk + BLK_SIZE - PTR_SIZE, &next, PTR_SIZE);
		writeBlockToDisk(wblk, waddr, buf);
		waddr++;
		wblk = getNewBlockInBuffer(buf);
		memset(wblk, 0, BLK_SIZE);
		wused = 0;
	}
	memcpy(wblk + wused, source, size);
	wused += size;
}
```

