Buffer *initBuffer(size_t bufSize, size_t blkSize, Buffer *buf)
{
	/* Each block slot in the buffer costs one extra byte that records
	 * whether the slot is available, followed by the block payload.
	 */
	buf->data = (unsigned char *)malloc(bufSize * sizeof(unsigned char));
	if (buf->data == NULL)
	{
		perror("Buffer Initialization Failed!\n");
		return NULL;
	}
	memset(buf->data, 0, bufSize);
	buf->numIO = 0;
	buf->bufSize = bufSize;
	buf->blkSize = blkSize;
	buf->numAllBlk = bufSize / (blkSize + 1);
	buf->numFreeBlk = buf->numAllBlk;
	return buf;
}

unsigned char *getNewBlockInBuffer(Buffer *buf)
{
	unsigned char *blkPtr;

	if (buf->numFreeBlk == 0)
	{
		perror("No Free Block in Buffer!\n");
		return NULL;
	}

	blkPtr = buf->data;
	for (size_t i = 0; i < buf->numAllBlk; i++)
	{
		if (*blkPtr == BLOCK_AVAILABLE)
		{
			*blkPtr = BLOCK_UNAVAILABLE;
			buf->numFreeBlk--;
			return blkPtr + 1; /* skip the availability flag byte */
		}
		blkPtr += buf->blkSize + 1;
	}

	return NULL;
}

