args.new_string:
void pushToWrite(Buffer *buf, unsigned char *source, size_t size, unsigned int addr, bool reset, bool push)
{
	/* State of the single shared writer. Result blocks are chained:
	 * the last PTR_SIZE bytes of a block hold the address of the next
	 * result block (0 marks the end of the chain).
	 */
	static unsigned char *wblk = NULL;
	static size_t wused = 0;
	static unsigned int waddr = 0;

	if (reset) /* start a new result chain at addr */
	{
		wblk = NULL;
		wused = 0;
		waddr = addr;
		return;
	}

	if (push) /* force-flush the partially filled block */
	{
		if (wblk != NULL)
		{
			unsigned int next = 0;
			memcpy(wblk + BLK_SIZE - PTR_SIZE, &next, PTR_SIZE);
			writeBlockToDisk(wblk, waddr, buf);
			wblk = NULL;
			wused = 0;
		}
		return;
	}

	if (wblk == NULL)
	{
		wblk = getNewBlockInBuffer(buf);
		memset(wblk, 0, BLK_SIZE);
		wused = 0;
	}

	if (wused + size > BLK_SIZE - PTR_SIZE) /* current block is full */
	{
		unsigned int next = waddr + 1;
		memcpy(wblk + BLK_SIZE - PTR_SIZE, &next, PTR_SIZE);
		writeBlockToDisk(wblk, waddr, buf);
		waddr++;
		wblk = getNewBlockInBuffer(buf);
		memset(wblk, 0, BLK_SIZE);
		wused = 0;
	}

	memcpy(wblk + wused, source, size);
	wused += size;
}

