void pushHashToWrite(Buffer *buf, Relation *R, unsigned int addr, bool reset, bool push)
{
	/* Tuples are routed to BUCKET_NUM buckets by attr1 % BUCKET_NUM.
	 * Each bucket owns one buffered block; a full block holds
	 * HASH_PER_BLK tuples (8 bytes each) plus a tuple count at byte
	 * offset HASH_PER_BLK * 8. Bucket b blocks are written to
	 * addr + b * 100 + k for k = 0, 1, ...
	 */
	static unsigned char *blks[BUCKET_NUM];
	static int cnt[BUCKET_NUM];
	static int blkIdx[BUCKET_NUM];
	static unsigned int base = 0;

	if (reset) /* start partitioning into buckets under addr */
	{
		for (int i = 0; i < BUCKET_NUM; i++)
		{
			blks[i] = NULL;
			cnt[i] = 0;
			blkIdx[i] = 0;
		}
		base = addr;
		return;
	}

	if (push) /* flush every partially filled bucket block */
	{
		for (int i = 0; i < BUCKET_NUM; i++)
		{
			if (blks[i] != NULL)
			{
				memcpy(blks[i] + HASH_PER_BLK * 2 * sizeof(int), &cnt[i], sizeof(int));
				writeBlockToDisk(blks[i], base + i * 100 + blkIdx[i], buf);
				blks[i] = NULL;
			}
		}
		return;
	}

	int bucket = R->attr1 % BUCKET_NUM;

	if (blks[bucket] == NULL)
	{
		blks[bucket] = getNewBlockInBuffer(buf);
		memset(blks[bucket], 0, BLK_SIZE);
		cnt[bucket] = 0;
	}

	memcpy(blks[bucket] + cnt[bucket] * 2 * sizeof(int), &R->attr1, sizeof(int));
	memcpy(blks[bucket] + (cnt[bucket] * 2 + 1) * sizeof(int), &R->attr2, sizeof(int));
	cnt[bucket]++;

	if (cnt[bucket] == HASH_PER_BLK) /* bucket block is full */
	{
		memcpy(blks[bucket] + HASH_PER_BLK * 2 * sizeof(int), &cnt[bucket], sizeof(int));
		writeBlockToDisk(blks[bucket], base + bucket * 100 + blkIdx[bucket], buf);
		blkIdx[bucket]++;
		blks[bucket] = NULL;
	}
}

