int mergeSort(Buffer *buf, bool choice)
{
	int blkNum = choice ? S_BLK_NUM : R_BLK_NUM;
	unsigned int baseAddr = choice ? S_ADDR : R_ADDR;
	unsigned int segAddr = choice ? MERGE_S_SEG_ADDR : MERGE_R_SEG_ADDR;
	unsigned int retAddr = choice ? MERGE_S_RET_ADDR : MERGE_R_RET_ADDR;
	int segBlks = (int)buf->numAllBlk - 1; /* leave one slot for merging output */
	int numRuns = (blkNum + segBlks - 1) / segBlks;
	Relation tuples[TUPLE_PER_BLK * 8];

	/* Pass 1: read M-1 blocks at a time, sort them in memory and
	 * write each sorted run to segAddr + i * segBlks.
	 */
	for (int i = 0; i < numRuns; i++)
	{
		int n = blkNum - i * segBlks < segBlks ? blkNum - i * segBlks : segBlks;
		int cnt = 0;

		for (int j = 0; j < n; j++)
		{
			unsigned char *blk = readBlockFromDisk(baseAddr + i * segBlks + j, buf);
			if (blk == NULL)
				return -1;
			readTuplesFromBlock(blk, tuples + cnt);
			cnt += TUPLE_PER_BLK;
			freeBlockInBuffer(blk, buf);
		}

		sort(tuples, tuples + cnt,
			[](const Relation &a, const Relation &b) { return a.attr1 < b.attr1; });

		for (int j = 0; j < n; j++) /* write the sorted run block by block */
		{
			unsigned char *blk = getNewBlockInBuffer(buf);
			unsigned int next = (j == n - 1) ? 0 : segAddr + i * segBlks + j + 1;

			memset(blk, 0, BLK_SIZE);
			for (int k = 0; k < TUPLE_PER_BLK; k++)
			{
				memcpy(blk + k * 2 * sizeof(int), &tuples[j * TUPLE_PER_BLK + k].attr1, sizeof(int));
				memcpy(blk + (k * 2 + 1) * sizeof(int), &tuples[j * TUPLE_PER_BLK + k].attr2, sizeof(int));
			}
			memcpy(blk + BLK_SIZE - PTR_SIZE, &next, PTR_SIZE);
			writeBlockToDisk(blk, segAddr + i * segBlks + j, buf);
		}
	}

	/* Pass 2: implemented below. */
	(void)retAddr;

	return 0;
}

