			if (rBlkIdx < R_BLK_NUM)
			{
				rBlk = readBlockFromDisk(MERGE_R_RET_ADDR + rBlkIdx, buf);
				readTuplesFromBlock(rBlk, rTuples);
			}
		}
	};
	auto advanceS = [&]() {
		si++;
		if (si == TUPLE_PER_BLK)
		{
			freeBlockInBuffer(sBlk, buf);
			sBlkIdx++;
			si = 0;
			if (sBlkIdx < S_BLK_NUM)
			{
				sBlk = readBlockFromDisk(MERGE_S_RET_ADDR + sBlkIdx, buf);
				readTuplesFromBlock(sBlk, sTuples);
			}
		}
	};

	while (rBlkIdx < R_BLK_NUM && sBlkIdx < S_BLK_NUM)
	{
		if (rTuples[ri].attr1 < sTuples[si].attr1)
		{
			advanceR();
		}
		else if (rTuples[ri].attr1 > sTuples[si].attr1)
		{
			advanceS();
		}
		else /* matching join key: emit the whole group cross product */
		{
			int key = rTuples[ri].attr1;
			vector<Relation> rGroup, sGroup;

			while (rBlkIdx < R_BLK_NUM && rTuples[ri].attr1 == key)
			{
				rGroup.push_back(rTuples[ri]);
				advanceR();
			}
			while (sBlkIdx < S_BLK_NUM && sTuples[si].attr1 == key)
			{
				sGroup.push_back(sTuples[si]);
				advanceS();
			}
			for (size_t a = 0; a < rGroup.size(); a++)
				for (size_t b = 0; b < sGroup.size(); b++)
					output(buf, SMJ_RET_ADDR, rGroup[a].attr1, rGroup[a].attr2, sGroup[b].attr2);
		}
	}

	if (rBlkIdx < R_BLK_NUM)
		freeBlockInBuffer(rBlk, buf);
	if (sBlkIdx < S_BLK_NUM)
		freeBlockInBuffer(sBlk, buf);

	pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, false, true);

	cout << "IO: " << buf->numIO << endl;

	return 0;
}

