static string trimStr(const string &s)
{
	size_t b = s.find_first_not_of(" \t\n\r");
	if (b == string::npos)
		return "";
	size_t e = s.find_last_not_of(" \t\n\r");
	return s.substr(b, e - b + 1);
}

static TreeNode *parseNode(const string &query)
{
	string q = trimStr(query);

	if (q.compare(0, 6, "SELECT") == 0 || q.compare(0, 10, "PROJECTION") == 0)
	{
		/* SELECT [ predicates ] ( subtree ) / PROJECTION [ attrs ] ( subtree ) */
		string type = (q[0] == 'S') ? "SELECT" : "PROJECTION";
		size_t lb = q.find('[');
		size_t rb = q.find(']', lb);
		size_t lp = q.find('(', rb);
		size_t rp = q.rfind(')');
		string info = trimStr(q.substr(lb + 1, rb - lb - 1));
		string inner = trimStr(q.substr(lp + 1, rp - lp - 1));

		TreeNode *node = new TreeNode(type, info);
		node->left = parseNode(inner);
		return node;
	}

	size_t jp = q.find(" JOIN ");
	if (jp != string::npos)
	{
		/* relation JOIN relation */
		TreeNode *node = new TreeNode("JOIN");
		node->left = new TreeNode("LEAF", trimStr(q.substr(0, jp)));
		node->right = new TreeNode("LEAF", trimStr(q.substr(jp + 6)));
		return node;
	}

	return new TreeNode("LEAF", q);
}

void parseQuery(TreeNode *root, string query)
{
	root->left = parseNode(query);
}

